(()=>{const root=document.querySelector('.dnct-guest-chat'),panel=root?.querySelector('.dnct-guest-panel'),launcher=root?.querySelector('.dnct-guest-launcher');if(!root||!panel||!launcher)return;const tabs=[...root.querySelectorAll('[data-guest-view]')],heading=root.querySelector('[data-guest-heading]'),copy=root.querySelector('[data-guest-copy]');const content={chat:['Zaloguj się, aby otworzyć czaty','Historia rozmów i kontakt z obsługą są dostępne po zalogowaniu do konta DNCT.'],tickets:['Zaloguj się, aby otworzyć tickety','Tworzenie zgłoszeń i podgląd odpowiedzi obsługi wymagają zalogowanego konta DNCT.']};const open=()=>{panel.hidden=false;launcher.setAttribute('aria-expanded','true');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)panel.animate([{opacity:0,transform:'translateY(12px) scale(.97)'},{opacity:1,transform:'none'}],{duration:240,easing:'cubic-bezier(.16,1,.3,1)'});tabs[0].focus();};const close=()=>{launcher.setAttribute('aria-expanded','false');const finish=()=>{panel.hidden=true;launcher.focus();};if(matchMedia('(prefers-reduced-motion: reduce)').matches)return finish();const animation=panel.animate([{opacity:1,transform:'none'},{opacity:0,transform:'translateY(10px) scale(.98)'}],{duration:170,easing:'ease-in'});animation.onfinish=finish;};launcher.onclick=()=>panel.hidden?open():close();root.querySelector('.dnct-guest-close').onclick=close;tabs.forEach(tab=>tab.onclick=()=>{tabs.forEach(item=>item.setAttribute('aria-selected',String(item===tab)));const [title,text]=content[tab.dataset.guestView];heading.textContent=title;copy.textContent=text;});})();
</script>
